typedef struct TCContext{TCDevice*d;HMODULE module;HWND window;UINT mode,base,minimum,expected,words;BOOL core;}TCContext;
static HRESULT bc_vb(TCContext*,UINT,DWORD,DWORD,UINT,TCVB**);static HRESULT bc_ib(TCContext*,UINT,DWORD,UINT,UINT,TCIB**);static HRESULT bc_stream(TCContext*,TCVB*);static HRESULT bc_indices(TCContext*,TCIB*);static void bc_bind_queries(TCContext*,TCVB*,TCIB*);static HRESULT bc_indexed_count(TCContext*,UINT,UINT);static HRESULT tc_fvf(TCDevice*);static void tc_read(TCContext*);static HRESULT tc_reset(TCContext*);
static void tc_check(BOOL ok,const char*s){if(!ok){tc_report(s);ExitProcess(1);}}static void tc_expect(HRESULT hr,const char*s){tc_check(hr==D3D_OK,s);}
typedef struct{float x,y,z,w;DWORD color;}BVertex;
static void bc_vertices(void*data,DWORD color){const float xy[4][2]={{-.5f,-.5f},{7.5f,-.5f},{-.5f,7.5f},{7.5f,7.5f}};BVertex*v=data;for(UINT n=0;n<6;n++)v[n]=(BVertex){100,100,.5f,1,0xffffff00u};for(UINT n=0;n<4;n++)v[n+1]=(BVertex){xy[n][0],xy[n][1],.5f,1,color};}
static void bc_setup(TCContext*c){tc_expect(TC_RS(c->d,7,0),"FAIL depth");tc_expect(TC_RS(c->d,137,0),"FAIL lighting");tc_expect(TC_RS(c->d,22,1),"FAIL cull");tc_expect(tc_fvf(c->d),"FAIL FVF");tc_expect(TC_TSS(c->d,0,1,3),"FAIL colorop");tc_expect(TC_TSS(c->d,0,3,0),"FAIL colorarg");tc_expect(TC_TSS(c->d,0,4,3),"FAIL alphaop");tc_expect(TC_TSS(c->d,0,6,0),"FAIL alphaarg");}
static void tc_cases(TCContext*c){TCVB*vb=NULL;TCIB*ib16=NULL,*ib32=NULL;tc_expect(bc_vb(c,120,0,0x44,1,&vb),"FAIL VB");tc_expect(bc_ib(c,12,0,101,1,&ib16),"FAIL IB16");tc_expect(bc_ib(c,24,0,102,1,&ib32),"FAIL IB32");TCVBDesc vd;TCIBDesc id;tc_expect(BC_VDESC(vb,&vd),"FAIL VB desc");tc_check(vd.Size==120&&vd.Pool==1&&vd.Usage==0&&vd.FVF==0x44,"FAIL VB metadata");tc_expect(BC_IDESC(ib16,&id),"FAIL IB16 desc");tc_check(id.Size==12&&id.Format==101&&id.Pool==1,"FAIL IB16 metadata");tc_expect(BC_IDESC(ib32,&id),"FAIL IB32 desc");tc_check(id.Size==24&&id.Format==102&&id.Pool==1,"FAIL IB32 metadata");TCDevice*parent=NULL;tc_expect(BC_VPARENT(vb,&parent),"FAIL VB parent");tc_check(parent==c->d,"FAIL parent identity");TC_DREL(parent);tc_expect(BC_IPARENT(ib32,&parent),"FAIL IB parent");tc_check(parent==c->d,"FAIL IB parent identity");TC_DREL(parent);
 const DWORD colors[]={0xffff0000u,0xff0000ffu,0xff00ff00u,0xff8000ffu};const UINT order[]={0,1,2,2,1,3};bc_setup(c);
 for(UINT step=0;step<4;step++){if(step==3){tc_expect(tc_reset(c),"FAIL managed Reset");bc_setup(c);}c->base=step==0?1:step<3?0xffffffffu:0;c->minimum=step==0?0:step<3?2:1;c->expected=colors[step];BLockPointer data=NULL;tc_expect(BC_VLOCK(vb,0,0,&data,0),"FAIL VB lock");bc_vertices(data,c->expected);tc_expect(BC_VUNLOCK(vb),"FAIL VB upload");TCIB*ib=step<2?ib16:ib32;tc_expect(BC_ILOCK(ib,0,0,&data,0),"FAIL IB lock");UINT delta=step==0?0:step<3?2:1;for(UINT n=0;n<6;n++)if(step<2)((WORD*)data)[n]=(WORD)(order[n]+delta);else((DWORD*)data)[n]=order[n]+delta;tc_expect(BC_IUNLOCK(ib),"FAIL IB upload");tc_expect(bc_stream(c,vb),"FAIL stream bind");tc_expect(bc_indices(c,ib),"FAIL indices bind");bc_bind_queries(c,vb,ib);
 tc_expect(TC_CLEAR(c->d,0,NULL,1,0xff010203,1,0),"FAIL clear");tc_expect(TC_BEGIN(c->d),"FAIL begin");tc_expect(bc_indexed_count(c,0,2),"FAIL indexed draw");tc_expect(TC_END(c->d),"FAIL end");tc_read(c);char line[180];wsprintfA(line,"IDXCORE FRAME index=%u mode=%u step=%u rawBase=%u bits=%u reset=%u readback=1",tc_frame_index++,c->mode,step,c->base,step<2?16:32,step==3);tc_report(line);
 if(step==0){tc_expect(TC_BEGIN(c->d),"FAIL guard begin");tc_expect(bc_indexed_count(c,0xffffffffu,0),"FAIL zero draw");tc_check(bc_indexed_count(c,1,2)==D3DERR_INVALIDCALL,"FAIL IB bound refusal");c->base=0x7fffffffu;tc_expect(bc_indices(c,ib),"FAIL maximum base bind");tc_check(bc_indexed_count(c,0,2)==D3DERR_INVALIDCALL,"FAIL base bound refusal");c->base=1;tc_expect(bc_indices(c,ib),"FAIL base restore");tc_expect(TC_END(c->d),"FAIL guard end");bc_bind_queries(c,vb,ib);}}
 tc_expect(bc_stream(c,NULL),"FAIL stream unbind");tc_expect(bc_indices(c,NULL),"FAIL indices unbind");tc_check(!BC_VREL(vb)&&!BC_IREL(ib16)&&!BC_IREL(ib32),"FAIL final buffer refs");char line[180];wsprintfA(line,"IDXCORE CHECK mode=%u signedBases=3 indexWidths=2 zeroDraw=1 boundRefusals=2 raw8Queries=1 reset=1 localWords=256 finalRefs=0",c->mode);tc_report(line);}
